<script setup lang="ts">
import {computed,onScopeDispose,ref,watch} from 'vue'
import {Delete,Plus} from '@element-plus/icons-vue'
import {can,projectId} from '@/core/session'
import {onIdentityChange} from '@/core/http'
import ReferenceIcon from '@/ui/ReferenceIcon.vue'
import {automationTimeCondition,automationTimeConditionAction,automationTimeConditionPresentation,automationWeekOptions,type AutomationNode,type AutomationTimeCondition} from './automation-editor-draft'
const props=defineProps<{condition?:AutomationNode;disabled?:boolean}>(),emit=defineEmits<{save:[node:AutomationNode];cancel:[]}>()
const initial=props.condition?automationTimeCondition(props.condition):undefined
const enabled=ref(initial?.enabled??true)
const form=ref<AutomationTimeCondition>(initial??{enabled:true,timeRanges:[{start:'08:00',end:'18:00'}],repeatType:'DAILY',weekDays:[],monthDays:[]}),error=ref('')
const permitted=computed(()=>can('rule:manage')&&!!projectId.value),blocked=computed(()=>props.disabled||!permitted.value)
function enabledChanged(next:string|number|boolean){if(!blocked.value&&typeof next==='boolean')enabled.value=next}
function repeatChanged(){if(blocked.value)return;if(form.value.repeatType==='DAILY'){form.value.weekDays=[];form.value.monthDays=[]}else if(form.value.repeatType==='WEEKLY'){form.value.monthDays=[];if(!form.value.weekDays.length)form.value.weekDays=[1]}else{form.value.weekDays=[];if(!form.value.monthDays.length)form.value.monthDays=[1]}}
function save(){if(blocked.value)return;try{if(!form.value.timeRanges.length)throw new Error('请至少添加一个时间范围');for(const [index,range] of form.value.timeRanges.entries()){if(!range.start)throw new Error(`第${index+1}个时间范围请填写开始时间`);if(!range.end)throw new Error(`第${index+1}个时间范围请填写结束时间`)}if(form.value.repeatType==='WEEKLY'&&!form.value.weekDays.length)throw new Error('请选择每周有效日');if(form.value.repeatType==='MONTHLY'&&!form.value.monthDays.length)throw new Error('请选择每月日期');emit('save',automationTimeConditionAction({...form.value,enabled:enabled.value}))}catch(cause){error.value=cause instanceof Error?cause.message:'请完善时间范围条件配置'}}
function cancel(){if(!props.disabled)emit('cancel')}
watch([projectId,permitted],()=>emit('cancel'))
const dispose=onIdentityChange(()=>emit('cancel'));onScopeDispose(dispose)
</script>
<template><el-dialog :model-value="true" :title="condition?'编辑条件':'配置条件'" width="800px" :lock-scroll="false" :close-on-click-modal="false" :close-on-press-escape="!disabled" :show-close="!disabled" append-to-body @update:model-value="cancel">
 <div class="automation-time-type"><span :style="{background:automationTimeConditionPresentation.background,color:automationTimeConditionPresentation.color}"><ReferenceIcon :glyph="automationTimeConditionPresentation.glyph"/></span><div><strong>{{automationTimeConditionPresentation.label}}</strong><p>{{automationTimeConditionPresentation.description}}</p></div></div>
 <el-form label-position="top" size="small" :disabled="blocked"><el-form-item label="启用条件"><el-switch :model-value="enabled" @update:model-value="enabledChanged" aria-label="启用时间条件" :disabled="blocked"/></el-form-item>
 <el-form-item label="重复类型"><el-radio-group v-model="form.repeatType" size="small" aria-label="时间重复类型" :disabled="blocked" @change="repeatChanged"><el-radio value="DAILY">每日</el-radio><el-radio value="WEEKLY">每周</el-radio><el-radio value="MONTHLY">每月</el-radio></el-radio-group></el-form-item>
 <el-form-item label="时间"><div class="automation-time-ranges"><div v-for="(range,index) in form.timeRanges" :key="index" class="automation-time-row"><el-time-picker v-model="range.start" value-format="HH:mm" format="HH:mm" placeholder="开始时间" size="small" :aria-label="`开始时间 ${index+1}`" :disabled="blocked"/><span>至</span><el-time-picker v-model="range.end" value-format="HH:mm" format="HH:mm" placeholder="结束时间" size="small" :aria-label="`结束时间 ${index+1}`" :disabled="blocked"/><el-button v-if="form.timeRanges.length>1" :icon="Delete" text size="small" class="automation-time-delete" :aria-label="`移除时间 ${index+1}`" :disabled="blocked" @click="form.timeRanges.splice(index,1)"/></div><el-button size="small" :icon="Plus" :disabled="blocked||form.timeRanges.length>=10" @click="form.timeRanges.push({start:'08:00',end:'18:00'})">添加时间</el-button><div class="form-item-tip">可添加多个时间段，满足任一时间段即可</div></div></el-form-item>
 <el-form-item v-if="form.repeatType==='WEEKLY'" label="每周有效日"><el-checkbox-group v-model="form.weekDays" aria-label="每周有效日" :disabled="blocked"><el-checkbox v-for="day in automationWeekOptions" :key="day.value" :value="day.value">{{day.label}}</el-checkbox></el-checkbox-group></el-form-item>
 <el-form-item v-if="form.repeatType==='MONTHLY'" label="每月日期"><el-checkbox-group v-model="form.monthDays" class="month-days-select" aria-label="每月日期" :disabled="blocked"><el-checkbox v-for="day in 31" :key="day" :value="day">{{day}}日</el-checkbox></el-checkbox-group></el-form-item></el-form>
 <el-alert v-if="error" :title="error" type="warning" :closable="false"/>
 <template #footer><el-button :disabled="disabled" @click="cancel">取消</el-button><el-button type="primary" :disabled="blocked" @click="save">确定</el-button></template>
</el-dialog></template>
<style scoped>.automation-time-type{display:flex;align-items:center;gap:14px;padding:14px 16px;background:#f8f9fa;border-radius:8px;margin-bottom:20px}.automation-time-type>span{display:flex;align-items:center;justify-content:center;width:42px;height:42px;border-radius:10px;flex:none;font-size:22px}.automation-time-type strong{font-size:15px;font-weight:600;color:#333}.automation-time-type p{font-size:13px;color:#888;margin:4px 0 0}.automation-time-ranges{width:100%}.automation-time-row{display:flex;align-items:center;gap:8px;margin-bottom:8px}.automation-time-row :deep(.el-date-editor.el-input){width:150px;flex:none}.automation-time-row>span{color:#6b7280}.automation-time-delete{color:#f56c6c}.form-item-tip{font-size:13px;color:#909399;margin-top:8px;line-height:1.4}.month-days-select{display:grid;grid-template-columns:repeat(10,minmax(0,1fr));gap:8px}.month-days-select :deep(.el-checkbox){margin-right:0;margin-bottom:0;justify-self:start}</style>
